using System.Collections.Generic;
using Tcs;

namespace LubGen;

/// <summary>Derives the C API header (include/lub/lub_api.h) from the stub.
/// C functions map 1:1 to stub functions, and structs 1:1 to classes.
/// </summary>
public static class CHeader
{
    public const string Prologue = """
        // The lub C API.
        // Generated by tools/lub-gen from cs-lib/lub_stub.cs (do not edit by hand;
        // regenerate: dotnet run --project tools/lub-gen -- header).
        //
        // Rules:
        //   - Functions take the context as the first argument, and functions that
        //     can fail return LubStatus.
        //     A failure is LUB_ERROR plus the lub_last_error() string; when the
        //     target of a query does not exist, it is LUB_NOT_FOUND (last_error is
        //     not written).
        //   - The only types are int32 / float / bool / UTF-8 byte sequences.
        //     Strings are LubStr (pointer + length, NUL termination not required).
        //   - Game memory is borrowed only for the duration of a call.
        //     Runtime memory is returned as a LubView or a runtime-owned array.
        //     Arrays are valid until the end of the frame.
        //     However, phys2d / phys3d arrays (the shapes of a body, query results)
        //     are valid until the next call that uses the same buffer, and arrays
        //     returned by functions called inside a visitor are released when the
        //     outer function returns (see the doc of the phys2d / phys3d sections).
        //     Things that live across frames are runtime-owned keyed resources, and
        //     the game holds only the key and an int32 handle.
        //   - Optional fields are has_x + x (the implementation fills in the
        //     default). Optional arguments are pointers (NULL = none).
        //   - Struct records of the stub (C# structs) are passed by value, even as
        //     arguments. Return values and outs are written through pointers, like
        //     other records.
        //   - Declarations that take version and data (use_* / snd) do not read data
        //     if version matches the stored one.
        //     A declaration that passes version with data NULL succeeds (LUB_OK) on
        //     a match, and if there is no matching resource (not created, already
        //     swept, or a different version), changes nothing and returns
        //     LUB_NOT_FOUND.
        //     NULL with version omitted is LUB_ERROR.
        //     Only for px of use_texture is NULL a declaration of an empty texture,
        //     so a NULL that does not match recreates it as an empty texture.
        //     So that the side holding the data can query before creating the data,
        //     a call with data == NULL and data_count == LUB_DATA_DEFERRED means
        //     "succeed (LUB_OK) only when version matches, otherwise change nothing
        //     and return LUB_NOT_FOUND".
        //   - Main thread only.
        #pragma once
        #include <stdbool.h>
        #include <stddef.h>
        #include <stdint.h>

        #ifdef __cplusplus
        extern "C" {
        #endif

        // Export of the shared library (lub_shared).
        // LUB_BUILD_SHARED is defined only when building the dll on Windows.
        #ifndef LUB_API
        #if defined(_WIN32) && defined(LUB_BUILD_SHARED)
        #define LUB_API __declspec(dllexport)
        #else
        #define LUB_API
        #endif
        #endif

        typedef struct LubContext LubContext;

        typedef enum LubStatus {
          LUB_OK = 0,
          LUB_ERROR = 1,
          LUB_NOT_FOUND = 2,
          LUB_BINDINGS_FULL = 3,
        } LubStatus;

        // data_count of a query that defers the data (see the rules above).
        #define LUB_DATA_DEFERRED (-1)

        // UTF-8 byte sequence.
        // ptr is valid for len bytes and needs no NUL termination.
        typedef struct LubStr {
          const char *ptr;
          int32_t len;
        } LubStr;

        // View into runtime memory.
        // Valid only during frame number `frame`.
        typedef struct LubView {
          const uint8_t *ptr;
          int32_t len;
          int32_t frame;
        } LubView;

        // Handle to a runtime-owned resource.
        // 0 = none.
        // Keeps the same value until the resource is swept, and stays valid across hot reload.
        // Passing a swept handle gives LUB_ERROR (redeclaring with the same key gives a different handle).
        typedef int32_t LubHandle;

        // One item of the bindings of a draw / dispatch.
        // name is the shader reflection name.
        // If handle is not 0, it binds a buffer / texture; otherwise it is a uniform value from values (count floats).
        typedef struct LubBinding {
          LubStr name;
          LubHandle handle;
          const float *values;
          int32_t count;
        } LubBinding;

        // Contents of a Gfx Bindings.
        // The caller allocates the block and initializes lub_bindings_size(scale) bytes with lub_bindings_init.
        // Freeing only requires releasing the block (the runtime allocates nothing).
        // A call for which the block is too small changes nothing and returns LUB_BINDINGS_FULL.
        // The caller inits a block with scale doubled, copies into it with lub_bindings_grow_into, and retries.
        // The block may be moved between calls.
        typedef struct LubBindings LubBindings;
        LUB_API size_t lub_bindings_size(int32_t scale);
        LUB_API void lub_bindings_init(LubBindings *b, int32_t scale);
        LUB_API int32_t lub_bindings_scale(const LubBindings *b);
        LUB_API void lub_bindings_grow_into(LubBindings *dst, LubBindings *src);

        // Message of the most recent LUB_ERROR.
        // Valid until the next API call.
        LUB_API const char *lub_last_error(LubContext *ctx);

        // Current frame number (compare with LubView.frame).
        LUB_API int32_t lub_frame_index(LubContext *ctx);

        """;

    public const string Epilogue = """

        // Form of lub_gfx_draw / lub_gfx_dispatch that passes name/value pairs as an array (used by .NET execution).
        LUB_API LubStatus lub_gfx_draw_items(LubContext *ctx, int32_t count,
                                             const LubBinding *bindings,
                                             int32_t bindings_count,
                                             const LubDrawOpts *opts,
                                             int32_t instances);
        LUB_API LubStatus lub_gfx_dispatch_items(LubContext *ctx, int32_t x,
                                                 int32_t y, int32_t z,
                                                 const LubBinding *bindings,
                                                 int32_t bindings_count,
                                                 const LubDispatchOpts *opts);

        #ifdef __cplusplus
        }
        #endif

        """;

    // ------------------------------------------------------------ names

    public static string TypeName(string csName) => "Lub" + csName;

    // Enums of the root (Lub) have no namespace level: Lub.EventKind → LubEventKind / LUB_EVENT_KIND_QUIT.
    public static string EnumName(string qualified)
    {
        var parts = qualified.Split('.');
        var kept = new List<string>();
        for (int i = 0; i < parts.Length; i++)
        {
            if (i == 0 && parts[0] == ApiModelLoader.RootNamespace) continue;
            kept.Add(parts[i]);
        }
        return "Lub" + string.Join("", kept);
    }

    public static string EnumMember(ApiEnum e, ApiEnumMember m) =>
        e.Namespace == ApiModelLoader.RootNamespace
            ? "LUB_" + HostNames.HostConst(e.Name) + "_" + m.HostName
            : "LUB_" + HostNames.HostConst(e.Namespace) + "_" + HostNames.HostConst(e.Name) + "_" + m.HostName;

    // lub.gfx.begin_pass → lub_gfx_begin_pass, lubx.vorbis.decode → lubx_vorbis_decode.
    public static string FunctionName(ApiNamespace ns, string hostName) => ns.HostPath.Replace(".", "_") + "_" + hostName;

    public static string Generate(ApiModel model)
    {
        var g = new CHeaderGen(model);
        return g.Run();
    }

    // ---------------------------------------------------------- helpers (shared with Facade)

    /// <summary>Type of a C declaration (struct field).</summary>
    public static void EmitStruct(Out sb, ApiType t)
    {
        var name = TypeName(t.Name);
        Comment(sb, t.Doc);
        sb.Write("typedef struct " + name + " {\n");
        bool any = false;
        bool hasFunc = false;
        foreach (var f in t.Fields)
        {
            if (f.Type.Kind == LubTypeKind.Func) hasFunc = true;
        }
        if (hasFunc)
        {
            sb.Write("  void *user; // passed to the callback\n");
            sb.Write("  // Called when the runtime releases the callback (it is replaced by the next\n");
            sb.Write("  // declaration, or the resource is swept). May be NULL.\n");
            sb.Write("  void (*user_release)(void *user);\n");
            any = true;
        }
        foreach (var f in t.Fields)
        {
            EmitField(sb, f);
            any = true;
        }
        if (!any) sb.Write("  int32_t unused; // avoids an empty struct\n");
        sb.Write("} " + name + ";\n\n");
    }

    private static void EmitField(Out sb, ApiField f)
    {
        var n = f.HostName;
        var tr = f.Type;
        var doc = f.Doc != "" ? " // " + f.Doc : "";
        string line;
        switch (tr.Kind)
        {
            case LubTypeKind.Int:
            case LubTypeKind.Double:
            case LubTypeKind.Bool:
                if (f.Optional) sb.Write("  bool has_" + n + ";\n");
                line = "  " + Scalar(tr) + " " + n + ";";
                break;
            case LubTypeKind.Enum:
                if (f.Optional) sb.Write("  bool has_" + n + ";\n");
                line = "  int32_t " + n + "; // " + EnumName(tr.Name);
                if (f.Doc != "") line += "。" + f.Doc;
                doc = "";
                break;
            case LubTypeKind.String:
                if (f.Bits)
                {
                    if (f.Optional) sb.Write("  bool has_" + n + ";\n");
                    line = "  uint64_t " + n + "; // bit mask (a hex string on the C# side)";
                    if (f.Doc != "") line += "。" + f.Doc;
                    doc = "";
                }
                else line = "  LubStr " + n + ";" + (f.Optional ? " // len 0 = none" : "");
                break;
            case LubTypeKind.Handle:
                line = "  LubHandle " + n + ";" + (f.Optional ? " // 0 = none" : "");
                break;
            case LubTypeKind.Keyed:
                line = "  LubStr " + n + ";";
                break;
            case LubTypeKind.View:
                line = "  LubView " + n + ";";
                break;
            case LubTypeKind.Record:
            case LubTypeKind.Struct:
                if (f.Optional) sb.Write("  bool has_" + n + ";\n");
                line = "  " + TypeName(tr.Name) + " " + n + ";";
                break;
            case LubTypeKind.List:
            {
                var elem = tr.Elem!;
                if (elem.Kind == LubTypeKind.Array)
                {
                    if (f.ArrayLen < 0) GenError.Report(f.Name + ": List of array needs [LubArray]");
                    line = "  const " + Scalar(elem.Elem!) + " (*" + n + ")[" + f.ArrayLen + "];\n  int32_t " + n + "_count;";
                }
                else if (f.ArrayLen >= 0)
                {
                    line = "  " + ElemType(elem) + " " + n + "[" + f.ArrayLen + "];\n  int32_t " + n + "_count;";
                }
                else
                {
                    line = "  const " + ElemType(elem) + " *" + n + ";" + (f.Optional ? " // NULL = none" : "") + "\n  int32_t " + n + "_count;";
                }
                break;
            }
            case LubTypeKind.Array:
            {
                if (f.ArrayLen < 0) GenError.Report(f.Name + ": array field needs [LubArray]");
                if (f.Optional) sb.Write("  bool has_" + n + ";\n");
                line = "  " + Scalar(tr.Elem!) + " " + n + "[" + f.ArrayLen + "];";
                break;
            }
            case LubTypeKind.Func:
                line = "  " + FuncPointer(tr, n) + ";";
                break;
            default:
                GenError.Report(f.Name + ": unsupported field type " + tr.ToString());
                line = "";
                break;
        }
        sb.Write(line + doc + "\n");
    }

    public static string Scalar(TypeRef tr)
    {
        switch (tr.Kind)
        {
            case LubTypeKind.Int:
                return "int32_t";
            case LubTypeKind.Double:
                return "float";
            case LubTypeKind.Bool:
                return "bool";
            case LubTypeKind.Enum:
                return "int32_t";
        }
        GenError.Report("not a scalar: " + tr.ToString());
        return "";
    }

    public static string ElemType(TypeRef elem)
    {
        switch (elem.Kind)
        {
            case LubTypeKind.Int:
            case LubTypeKind.Double:
            case LubTypeKind.Bool:
            case LubTypeKind.Enum:
                return Scalar(elem);
            case LubTypeKind.String:
                return "LubStr";
            case LubTypeKind.Handle:
                return "LubHandle";
            case LubTypeKind.Record:
                return TypeName(elem.Name);
        }
        GenError.Report("unsupported element type " + elem.ToString());
        return "";
    }

    public static string FuncReturn(TypeRef ret)
    {
        switch (ret.Kind)
        {
            case LubTypeKind.Void:
                return "void";
            case LubTypeKind.Bool:
                return "bool";
            case LubTypeKind.Double:
                return "float";
            case LubTypeKind.Int:
                return "int32_t";
        }
        GenError.Report("unsupported callback return " + ret.ToString());
        return "";
    }

    public static string FuncParams(TypeRef fn)
    {
        var parts = new List<string>();
        parts.Add("void *user");
        int i = 0;
        foreach (var p in fn.FuncParams!)
        {
            string pn = Text.Sub("abcdefghijklmnopqrstuvwxyz", i, 1);
            if (p.Kind == LubTypeKind.Record) parts.Add("const " + TypeName(p.Name) + " *" + pn);
            else if (p.IsScalar) parts.Add(Scalar(p) + " " + pn);
            else GenError.Report("unsupported callback param " + p.ToString());
            i++;
        }
        return string.Join(", ", parts);
    }

    public static string FuncPointer(TypeRef fn, string name) => FuncReturn(fn.FuncReturn!) + " (*" + name + ")(" + FuncParams(fn) + ")";

    public static void Comment(Out sb, string doc)
    {
        if (doc == "") return;
        foreach (var line in WrapText(doc, 76)) sb.Write("// " + line + "\n");
    }

    // Wraps at display width (CJK is 2).
    // Wrap points are after a space, or before a CJK character (excluding punctuation and closing brackets).
    // Only spaces from the original text are used.
    // Positions are counted in UTF-16 units, as in the C# version (characters outside the BMP are 2 units, with width 1 each).
    public static List<string> WrapText(string text, int width)
    {
        var units = new List<int>();
        foreach (var r in text.EnumerateRunes())
        {
            int v = r.Value;
            if (v >= 0x10000)
            {
                units.Add(0xD800);
                units.Add(0xDC00);
            }
            else units.Add(v);
        }
        var runes = new List<string>();
        foreach (var r in text.EnumerateRunes())
        {
            runes.Add(r.ToString());
            if (r.Value >= 0x10000) runes.Add("");
        }
        var result = new List<string>();
        int start = 0;
        int len = units.Count;
        while (start < len)
        {
            int w = 0;
            int lastBreak = -1;
            int i = start;
            for (; i < len; i++)
            {
                int c = units[i];
                int cw = IsWide(c) ? 2 : 1;
                if (w + cw > width && lastBreak > start) break;
                if (c == ' ') lastBreak = i + 1;
                else if (IsWide(c) && !IsWidePunct(c) && i > start && units[i - 1] != ' ') lastBreak = i;
                w += cw;
            }
            int end = i >= len ? len : lastBreak;
            var piece = new List<string>();
            for (int k = start; k < end; k++) piece.Add(runes[k]);
            result.Add(string.Join("", piece).Trim());
            start = end;
            while (start < len && units[start] == ' ') start++;
        }
        return result;
    }

    private static bool IsWide(int c) => c > 0x2E7F && !(c >= 0xD800 && c <= 0xDFFF);

    private static bool IsWidePunct(int c)
    {
        foreach (var r in "。、」』）］〕〉》・ー：；！？".EnumerateRunes())
        {
            if (r.Value == c) return true;
        }
        return false;
    }

    // UTF-16 length (string.Length in the C# version)
    public static int Utf16Length(string s)
    {
        int n = 0;
        foreach (var r in s.EnumerateRunes()) n += r.Value >= 0x10000 ? 2 : 1;
        return n;
    }

    // Wraps arguments at 80 columns, clang-format style.
    public static string Wrap(string head, string rest)
    {
        int headLen = Utf16Length(head);
        var indent = Text.Repeat(" ", headLen);
        var parts = rest.Split(", ");
        var sb = new List<string>();
        sb.Add(head);
        int col = headLen;
        for (int i = 0; i < parts.Length; i++)
        {
            var piece = parts[i] + (i + 1 < parts.Length ? "," : "");
            int pl = Utf16Length(piece);
            if (col + pl + (i > 0 ? 1 : 0) > 80 && i > 0)
            {
                sb.Add("\n");
                sb.Add(indent);
                col = headLen;
            }
            else if (i > 0)
            {
                sb.Add(" ");
                col++;
            }
            sb.Add(piece);
            col += pl;
        }
        return string.Join("", sb);
    }
}

internal sealed class CHeaderGen
{
    private ApiModel model;
    private Out sb = new Out();
    private Dictionary<string, ApiType> byName = new Dictionary<string, ApiType>();
    private HashSet<string> done = new HashSet<string>();
    private HashSet<string> visiting = new HashSet<string>();

    public CHeaderGen(ApiModel model)
    {
        this.model = model;
    }

    public string Run()
    {
        sb.Write(CHeader.Prologue);
        EmitEnums();
        EmitConsts();
        EmitTypes();
        foreach (var ns in model.Namespaces) EmitNamespaceFunctions(ns);
        sb.Write(CHeader.Epilogue);
        return sb.ToString();
    }

    private static string FnTypedefName(ApiNamespace ns, ApiFunction f, ApiParam p) =>
        "Lub" + ns.Name + f.Name + Text.UpperFirst(p.Name) + "Fn";

    // ------------------------------------------------------------ enums

    private void EmitEnums()
    {
        foreach (var ns in model.Namespaces)
        {
            foreach (var e in ns.Enums)
            {
                CHeader.Comment(sb, e.Doc);
                sb.Write("typedef enum " + CHeader.EnumName(ns.Name + "." + e.Name) + " {\n");
                foreach (var m in e.Members)
                {
                    sb.Write("  " + CHeader.EnumMember(e, m) + " = " + m.Value + ",");
                    if (m.Doc != "") sb.Write(" // " + m.Doc);
                    sb.Write("\n");
                }
                sb.Write("} " + CHeader.EnumName(ns.Name + "." + e.Name) + ";\n\n");
            }
        }
    }

    private void EmitConsts()
    {
        foreach (var ns in model.Namespaces)
        {
            foreach (var c in ns.Consts)
            {
                if (c.Value.Kind != ValueKind.Int) continue;
                CHeader.Comment(sb, c.Doc);
                sb.Write("#define LUB_" + HostNames.HostConst(ns.Name) + "_" + c.HostName + " " + c.Value.I + "\n\n");
            }
        }
    }

    // ------------------------------------------------------------ types

    private void EmitTypes()
    {
        var records = new List<ApiType>();
        foreach (var t in model.Types)
        {
            if (t.Kind == "record" || t.Kind == "struct") records.Add(t);
        }
        foreach (var t in records) byName[t.Name] = t;
        foreach (var t in records) Visit(t);
    }

    private void Visit(ApiType t)
    {
        if (done.Contains(t.Name)) return;
        if (!visiting.Add(t.Name))
        {
            GenError.Report("type cycle at " + t.Name);
            return;
        }
        foreach (var dep in Deps(t))
        {
            ApiType? d;
            if (byName.TryGetValue(dep, out d)) Visit(d!);
        }
        visiting.Remove(t.Name);
        done.Add(t.Name);
        CHeader.EmitStruct(sb, t);
    }

    private static List<string> Deps(ApiType t)
    {
        var r = new List<string>();
        foreach (var f in t.Fields) Deps(f.Type, r);
        return r;
    }

    private static void Deps(TypeRef tr, List<string> r)
    {
        switch (tr.Kind)
        {
            case LubTypeKind.Record:
            case LubTypeKind.Struct:
                r.Add(tr.Name);
                break;
            case LubTypeKind.List:
            case LubTypeKind.Array:
                Deps(tr.Elem!, r);
                break;
            case LubTypeKind.Func:
                foreach (var p in tr.FuncParams!) Deps(p, r);
                break;
        }
    }

    // -------------------------------------------------------- functions

    private void EmitNamespaceFunctions(ApiNamespace ns)
    {
        string label = ns.HostPath == "lub" ? "core" : ns.HostRoot == "lub" ? Text.From(ns.HostPath, Text.Len("lub.")) : ns.HostPath;
        int dashes = 70 - CHeader.Utf16Length(label);
        if (dashes < 1) dashes = 1;
        sb.Write("// " + Text.Repeat("-", dashes) + " " + label + "\n");
        if (ns.Doc != "") CHeader.Comment(sb, ns.Doc);
        sb.Write("\n");
        foreach (var f in ns.StaticFields)
        {
            CHeader.Comment(sb, f.Doc);
            sb.Write("LUB_API " + ReturnCType(f.Type) + " " + CHeader.FunctionName(ns, f.HostName) + "(LubContext *ctx);\n\n");
        }
        foreach (var f in ns.Functions)
        {
            if (f.NoC) continue;
            foreach (var p in f.Params)
            {
                if (p.Type.Kind != LubTypeKind.Func) continue;
                var fn = p.Type;
                sb.Write("typedef " + CHeader.FuncReturn(fn.FuncReturn!) + " (*" + FnTypedefName(ns, f, p) + ")(" + CHeader.FuncParams(fn) + ");\n");
            }
            CHeader.Comment(sb, f.Doc);
            sb.Write(Prototype(ns, f) + "\n\n");
        }
    }

    private static string ReturnCType(TypeRef tr)
    {
        switch (tr.Kind)
        {
            case LubTypeKind.Void:
                return "void";
            case LubTypeKind.Int:
                return "int32_t";
            case LubTypeKind.Double:
                return "float";
            case LubTypeKind.Bool:
                return "bool";
            case LubTypeKind.Enum:
                return "int32_t";
            case LubTypeKind.Handle:
                return "LubHandle";
        }
        GenError.Report("unsupported direct return " + tr.ToString());
        return "";
    }

    private string Prototype(ApiNamespace ns, ApiFunction f)
    {
        var args = new List<string>();
        args.Add("LubContext *ctx");
        foreach (var p in f.Params)
        {
            if (!p.IsOut && !p.IsCount) InParam(ns, f, p, args);
        }
        foreach (var p in f.Params)
        {
            if (!p.IsOut) continue;
            OutParam(p.Type, p.HostName, args);
            if (p.Type.Kind == LubTypeKind.Record && p.Type.Nullable) args.Add("bool *has_" + p.HostName);
        }
        string ret;
        var r = f.Return;
        if (f.NoFail)
        {
            if (r.Kind == LubTypeKind.Void || r.Kind == LubTypeKind.Int || r.Kind == LubTypeKind.Double || r.Kind == LubTypeKind.Bool
                || r.Kind == LubTypeKind.Enum || r.Kind == LubTypeKind.Handle)
                ret = ReturnCType(r);
            else
            {
                ret = "void";
                OutParam(r, "out", args);
            }
        }
        else
        {
            ret = "LubStatus";
            if (r.Kind != LubTypeKind.Void)
            {
                OutParam(r, "out", args);
                if (r.Nullable && (r.IsScalar || (r.Kind == LubTypeKind.Record && f.Maybe))) args.Add("bool *has");
            }
        }
        return CHeader.Wrap("LUB_API " + ret + " " + CHeader.FunctionName(ns, f.HostName) + "(", string.Join(", ", args) + ");");
    }

    private static void InParam(ApiNamespace ns, ApiFunction f, ApiParam p, List<string> o)
    {
        var n = p.HostName;
        var tr = p.Type;
        switch (tr.Kind)
        {
            case LubTypeKind.Int:
            case LubTypeKind.Double:
            case LubTypeKind.Bool:
            case LubTypeKind.Enum:
                o.Add(tr.Nullable ? "const " + CHeader.Scalar(tr) + " *" + n : CHeader.Scalar(tr) + " " + n);
                return;
            case LubTypeKind.String:
                o.Add("LubStr " + n);
                return;
            case LubTypeKind.Handle:
                o.Add("LubHandle " + n);
                return;
            case LubTypeKind.Keyed:
                o.Add("LubStr " + n);
                return;
            case LubTypeKind.View:
                o.Add("const uint8_t *" + n);
                o.Add("int32_t " + n + "_len");
                return;
            case LubTypeKind.Record:
                o.Add("const " + CHeader.TypeName(tr.Name) + " *" + n);
                return;
            case LubTypeKind.Struct:
                o.Add(CHeader.TypeName(tr.Name) + " " + n);
                return;
            case LubTypeKind.List:
                o.Add("const " + CHeader.ElemType(tr.Elem!) + " *" + n);
                o.Add("int32_t " + n + "_count");
                return;
            case LubTypeKind.Func:
                o.Add(FnTypedefName(ns, f, p) + " " + n);
                o.Add("void *" + n + "_user");
                return;
            case LubTypeKind.Native:
                o.Add(CHeader.TypeName(tr.Name) + " *" + n);
                return;
            case LubTypeKind.Array:
                if (tr.Elem!.Kind == LubTypeKind.Double)
                {
                    o.Add("const float *" + n);
                    o.Add("int32_t " + n + "_count");
                    return;
                }
                break;
        }
        GenError.Report(ns.Name + "." + f.Name + ": unsupported parameter " + p.Name + ": " + tr.ToString());
    }

    private static void OutParam(TypeRef tr, string n, List<string> o)
    {
        switch (tr.Kind)
        {
            case LubTypeKind.Int:
            case LubTypeKind.Double:
            case LubTypeKind.Bool:
            case LubTypeKind.Enum:
                o.Add(CHeader.Scalar(tr) + " *" + n);
                return;
            case LubTypeKind.String:
                o.Add("LubStr *" + n);
                return;
            case LubTypeKind.Handle:
                o.Add("LubHandle *" + n);
                return;
            case LubTypeKind.View:
                o.Add("LubView *" + n);
                return;
            case LubTypeKind.Record:
            case LubTypeKind.Struct:
                o.Add(CHeader.TypeName(tr.Name) + " *" + n);
                return;
            case LubTypeKind.List:
                o.Add("const " + CHeader.ElemType(tr.Elem!) + " **" + n);
                o.Add("int32_t *" + n + "_count");
                return;
        }
        GenError.Report("unsupported out / return type " + tr.ToString());
    }
}
